contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount, "insufficient balance");

        uint256 testBalBefore = address(this).balance;
        uint256 cBalBefore = address(c).balance;

        c.Command{value: amount}(address(this), ""); if (__ESBMC_reverted()) return;

        bool reverted;
        c.withdraw(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 testBalAfter = address(this).balance;
        uint256 cBalAfter = address(c).balance;

        assert(!(!reverted && cBalAfter > 0) || testBalAfter >= testBalBefore || cBalBefore == 0 || cBalBefore == amount);
    }

    receive() external payable {}
    fallback() external payable {}
}

