pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MultiplicatorX3 c;

    function setUp() public {
        c = new MultiplicatorX3();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        uint256 testBalBefore = address(this).balance;
        uint256 cBalBefore = address(c).balance;
        try c.Command{value: amount}(address(this), "") {} catch { return; }
        bool reverted;
        try c.withdraw() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 testBalAfter = address(this).balance;
        uint256 cBalAfter = address(c).balance;
        assertTrue(!(!reverted && cBalAfter > 0) || testBalAfter >= testBalBefore || cBalBefore == 0 || cBalBefore == amount);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}

    fallback() external payable {}
}
